        v_edgewidth = (v_size / a_size) * a_edgewidth;
    }
    else {
        // scaling == "fixed": marker is always the same number of pixels
        v_size = a_size * u_px_scale;
        v_edgewidth = a_edgewidth * u_px_scale;
    }

